package com.kinectmessaging.config

import com.kinectmessaging.config.client.MjmlClient
import com.kinectmessaging.config.model.MjmlRequest
import com.kinectmessaging.config.model.MjmlResponse
import com.kinectmessaging.config.model.TemplateEntity
import com.kinectmessaging.libs.model.*
import io.mockk.every
import io.quarkiverse.test.junit.mockk.InjectMock
import io.quarkus.test.junit.QuarkusTest
import io.restassured.RestAssured.given
import io.restassured.http.ContentType
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import org.apache.http.HttpStatus
import org.eclipse.microprofile.rest.client.inject.RestClient
import org.hamcrest.core.IsEqual.equalTo
import org.junit.jupiter.api.Assertions
import org.junit.jupiter.api.Test
import java.time.LocalDateTime
import kotlin.io.encoding.ExperimentalEncodingApi

@QuarkusTest
class TemplateResourceTest {
 private final val baseUrl = "/kinect/messaging/config/template"

 @InjectMock
 @field:RestClient
 private lateinit var mjmlClient: MjmlClient

  private final val auditInfo = Audit(
   createdBy = "Unit Test 1",
   createdTime = LocalDateTime.now().toString(),
   updatedBy = "Unit Test 1",
   updatedTime = LocalDateTime.now().toString()
  )

 val templateData = mutableListOf(
  KTemplate(
   templateId = "1",
   templateName = "Test Get By Id 1",
   templateType = TemplateType.CONTROL,
   templateLanguage = Language.EN,
   templateContent = "SGkge2N1c3RvbWVyLm5hbWV9LAogICAgV2UgaG9wZSB0aGlzIGVtYWlsIGZpbmQgeW91IHdlbGwu",
   auditInfo = auditInfo
  ),
  KTemplate(
   templateId = "2",
   templateName = "Test Get By Id 2",
   templateType = TemplateType.CONTROL,
   templateLanguage = Language.EN,
   templateContent = "",
   auditInfo = auditInfo
  )
 )

 val htmlTemplateResponse = ""

  @Test
 fun createTextTemplate() {
   val requestInput = Json.encodeToString(templateData[0])
   given()
    .header("Content-Type", ContentType.JSON)
    .body(requestInput)
    .`when`().post(baseUrl)
    .then()
    .assertThat()
    .statusCode(HttpStatus.SC_OK)
   Assertions.assertEquals(1, TemplateEntity.count("_id", templateData[0].templateId))
  }

 @Test
 fun createHtmlTemplate() {
  val requestInput = Json.encodeToString(templateData[1])
  given()
   .header("Content-Type", ContentType.JSON)
   .body(requestInput)
   .`when`().post(baseUrl)
   .then()
   .assertThat()
   .statusCode(HttpStatus.SC_OK)
  Assertions.assertEquals(1, TemplateEntity.count("_id", templateData[1].templateId))
 }

@Test
 fun getTemplateById() {

 given()
  .`when`().get("$baseUrl/${templateData[0].templateId}")
  .then()
  .assertThat()
  .statusCode(HttpStatus.SC_OK)
  .body("templateId",equalTo(templateData[0].templateId))
 }

@Test
 fun getTemplates() {

 // given
 val pageNo = 1
 val pageSize = 1
 val sortBy = "templateName"
 given()
  .`when`().get("$baseUrl?_start=$pageNo&_end=$pageSize&_sort=$sortBy&_order=ASC")
  .then()
  .assertThat()
  .statusCode(HttpStatus.SC_OK)
 Assertions.assertEquals(1, TemplateEntity.count("_id", templateData[0].templateId))
 }

 @Test
 fun `given personalization Request with no data then get HTML Template`(){

  //given
  val personalizationData = mutableMapOf(
   Pair("promotion", mutableMapOf(Pair("name", "New Year Promotion"))),
   Pair("customer", mutableMapOf(Pair("name", "Tester One")))
  )
  val givenInput = TemplatePersonalizationRequest(
   "1",
   null,
   personalizationData
  )

  every { mjmlClient.renderMjmlToHtml(any(String::class), any(MjmlRequest::class), any(String::class)) } returns MjmlResponse(
   html = htmlTemplateResponse,
   json = null,
   errors = null
  )

  val response = given()
   .header("Content-Type", ContentType.JSON)
   .body(givenInput)
   .`when`().post("$baseUrl/personalize")
   .then()
   .assertThat()
   .statusCode(HttpStatus.SC_OK)
   .extract()

  Assertions.assertEquals( true, response.body().asString().contains("Tester One"),)

 }

 @OptIn(ExperimentalEncodingApi::class)
 @Test
 fun `given personalization Request with data then get HTML Template`(){

  //given
  val personalizationData = mutableMapOf(
   Pair("promotion", mutableMapOf(Pair("name", "New Year Promotion"))),
   Pair("customer", mutableMapOf(Pair("name", "Tester One")))
  )
  val givenInput = TemplatePersonalizationRequest(
   null,
   "2",
   personalizationData
  )

  every { mjmlClient.renderMjmlToHtml(any(String::class), any(MjmlRequest::class), any(String::class)) } returns MjmlResponse(
   html = htmlTemplateResponse,
   json = null,
   errors = null
  )

  val response = given()
   .header("Content-Type", ContentType.JSON)
   .body(givenInput)
   .`when`().post("$baseUrl/personalize")
   .then()
   .assertThat()
   .statusCode(HttpStatus.SC_OK)
   .extract()
  Assertions.assertEquals( true, response.body().asString().contains("<html"),)

 }
}